const visual = {
  prepare: function (input) {
    var texts = [
      'u = x/h',
      'u = 0',
      'x = 0',
      'u = 1/2',
      'x = h/2',
      'u = 1',
      'x = h',
      '瓶口基准线',
      'h',
      'x',
      'u = 1 时木塞底部到达瓶口基准线'
    ];
    return texts.map(function (t) { return { kind: 'text', payload: t }; });
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var baselineY = 220;
    var centers = [110, 300, 490];
    var neckHalf = 26;
    var corkHalf = 16;
    var h = 64;
    var corkH = 60;
    var initialBottomY = baselineY + h;
    var bodyBottomY = 380;
    var bodyHalf = 60;
    var shoulderY = 290;
    var neckBottomY = 290;
    var paths = [];
    var children = [];
    function addPath(id, commands, stroke, fill, strokeWidth, dash) {
      paths.push({ id: id, commands: commands });
      var node = { type: 'path', pathId: id, stroke: stroke, fill: fill, strokeWidth: strokeWidth || 1 };
      if (dash) { node.strokeDasharray = dash; }
      children.push(node);
    }
    function addLabel(text, x, y, fontSize, fill, anchor) {
      children.push({ type: 'label', text: text, x: x, y: y, fontSize: fontSize, fill: fill, anchor: anchor });
    }
    function poly(points) { return visualSdk.polyline(points); }
    addPath('baseline', poly([[40, baselineY], [560, baselineY]]), '#8a97a8', 'none', 1.2);
    for (var i = 0; i < centers.length; i++) {
      var cx = centers[i];
      var p = 'p' + i;
      addPath(p + '-neck-l', poly([[cx - neckHalf, baselineY], [cx - neckHalf, neckBottomY]]), '#26354a', 'none', 1.5);
      addPath(p + '-neck-r', poly([[cx + neckHalf, baselineY], [cx + neckHalf, neckBottomY]]), '#26354a', 'none', 1.5);
      addPath(p + '-sh-l', poly([[cx - neckHalf, neckBottomY], [cx - bodyHalf, shoulderY]]), '#26354a', 'none', 1.5);
      addPath(p + '-sh-r', poly([[cx + neckHalf, neckBottomY], [cx + bodyHalf, shoulderY]]), '#26354a', 'none', 1.5);
      addPath(p + '-body-l', poly([[cx - bodyHalf, shoulderY], [cx - bodyHalf, bodyBottomY]]), '#26354a', 'none', 1.5);
      addPath(p + '-body-r', poly([[cx + bodyHalf, shoulderY], [cx + bodyHalf, bodyBottomY]]), '#26354a', 'none', 1.5);
      addPath(p + '-body-b', poly([[cx - bodyHalf, bodyBottomY], [cx + bodyHalf, bodyBottomY]]), '#26354a', 'none', 1.5);
      addPath(p + '-initial', poly([[cx - neckHalf, initialBottomY], [cx + neckHalf, initialBottomY]]), '#b0b8c4', 'none', 1, '4 3');
      var u = i / 2;
      var xDisp = u * h;
      var bottomY = initialBottomY - xDisp;
      var topY = bottomY - corkH;
      var corkPts = [[cx - corkHalf, topY], [cx + corkHalf, topY], [cx + corkHalf, bottomY], [cx - corkHalf, bottomY], [cx - corkHalf, topY]];
      addPath(p + '-cork', poly(corkPts), '#7a5a3a', '#e6c9a8', 1.8);
      var stageLabel = i === 0 ? 'u = 0' : (i === 1 ? 'u = 1/2' : 'u = 1');
      var xLabel = i === 0 ? 'x = 0' : (i === 1 ? 'x = h/2' : 'x = h');
      addLabel(stageLabel, cx, 80, 18, '#1f2a37', 'middle');
      addLabel(xLabel, cx, 108, 15, '#1f2a37', 'middle');
      if (i > 0) {
        var arrowX = cx + neckHalf + 13;
        addPath(p + '-xarrow', visualSdk.arrow(arrowX, initialBottomY, arrowX, bottomY, {}), '#c0392b', 'none', 2);
        addLabel('x', arrowX + 10, (initialBottomY + bottomY) / 2, 14, '#c0392b', 'start');
      }
      if (i === 0) {
        var dimX = cx - neckHalf - 24;
        addPath(p + '-hdim', poly([[dimX, baselineY], [dimX, initialBottomY]]), '#555', 'none', 1);
        addPath(p + '-hdim-t1', poly([[dimX - 6, baselineY], [dimX + 6, baselineY]]), '#555', 'none', 1);
        addPath(p + '-hdim-t2', poly([[dimX - 6, initialBottomY], [dimX + 6, initialBottomY]]), '#555', 'none', 1);
        addLabel('h', dimX - 10, (baselineY + initialBottomY) / 2, 16, '#333', 'end');
      }
    }
    addLabel('u = x/h', W / 2, 38, 20, '#1f2a37', 'middle');
    addLabel('瓶口基准线', 560, baselineY - 10, 13, '#5a6b7f', 'end');
    addLabel('u = 1 时木塞底部到达瓶口基准线', W / 2, 410, 13, '#5a6b7f', 'middle');
    return {
      schemaVersion: 1,
      sceneId: 'cork-pull-stages',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
